<script setup lang="ts">
import {computed,ref} from 'vue'
import type {Editor} from '../lib/editor'
import {newId,type TransportConfig} from '../lib/model'
const props=defineProps<{editor:Editor}>()
const selectedId=ref('')
const items=computed(()=>props.editor.project.value.transports??[])
const selected=computed(()=>items.value.find(item=>item.id===selectedId.value)??items.value[0])
function add(){const id=newId('transport');props.editor.mutate(project=>{project.schemaVersion=4;project.transports??=[];project.transports.push({id,name:'USB Printer',kind:'usb-printer',interfaceGuid:'{28D78FAD-5A12-11D1-AE5B-0000F803A8C2}',vendorId:0,productId:0,packetSize:64})});selectedId.value=id}
function update(key:keyof TransportConfig,value:unknown){if(selected.value)props.editor.mutate(()=>{(selected.value as any)[key]=value})}
</script>
<template><section class="transport-resources"><aside><button class="text-button" :disabled="editor.readOnly.value" @click="add">＋ 添加 USB 传输</button><button v-for="item in items" :key="item.id" class="transport-item" :class="{active:selected?.id===item.id}" @click="selectedId=item.id"><strong>{{item.name}}</strong><small>{{item.id}}</small></button></aside><fieldset v-if="selected" :disabled="editor.readOnly.value"><div class="transport-heading"><code>{{selected.id}}</code><button class="text-button" @click="editor.mutate(project=>project.transports=items.filter(item=>item.id!==selected!.id))">删除</button></div><label>名称<input :value="selected.name" @change="update('name',($event.target as HTMLInputElement).value)"></label><label>接口 GUID<input :value="selected.interfaceGuid" @change="update('interfaceGuid',($event.target as HTMLInputElement).value)"></label><label>Vendor ID（十进制或 0x）<input :value="`0x${selected.vendorId.toString(16).padStart(4,'0')}`" @change="update('vendorId',Number(($event.target as HTMLInputElement).value))"></label><label>Product ID（十进制或 0x）<input :value="`0x${selected.productId.toString(16).padStart(4,'0')}`" @change="update('productId',Number(($event.target as HTMLInputElement).value))"></label><label>数据包大小<input type="number" min="1" :value="selected.packetSize??64" @change="update('packetSize',Number(($event.target as HTMLInputElement).value))"></label><p>流程中的传输节点引用此资源。协议组帧与解析由 Python 代码节点完成。</p></fieldset><p v-else class="transport-empty">添加传输资源，再在流程中连接枚举、打开和收发节点。</p></section></template>
<style scoped>.transport-resources{display:flex;min-height:0;min-width:0;flex:1}.transport-resources aside{width:200px;padding:8px;overflow:auto;border-right:1px solid var(--line);flex-shrink:0}.transport-item{display:flex;flex-direction:column;text-align:left;gap:4px;width:100%;padding:6px;border:0;background:transparent;font-size:12px}.transport-item.active{background:#e8f2fc;color:#0f6cbd}.transport-item small{font-size:10px;overflow-wrap:anywhere}.transport-resources fieldset{flex:1;min-width:0;overflow:auto;display:grid;grid-template-columns:repeat(2,minmax(140px,1fr));gap:8px 14px;align-content:start;border:0;padding:8px 14px;margin:0}.transport-heading{grid-column:1/-1;display:flex;justify-content:space-between}.transport-resources label{font-size:11px;margin:0}.transport-resources input{font-size:12px;height:28px}.transport-resources p{font-size:11px;color:#68788a;grid-column:1/-1}.transport-empty{padding:12px}</style>
